public class Main {
    public static void main(String[] args) {
        int ricePrice = 120;
        int sugarPrice = 45;
        int oilPrice = 160;

        int subtotal = ricePrice + sugarPrice + oilPrice;
        int finalBill = subtotal + 30;

        System.out.println("Subtotal: Rs " + subtotal);
        System.out.println("Final Bill: Rs " + finalBill);
    }
}

