public class Main {
    public static void main(String[] args) {
        int studentId = 2026489;
        int lastDigit = studentId % 10;
        int prefix = studentId / 10;

        System.out.println("Original ID: " + studentId);
        System.out.println("Last Digit: " + lastDigit);
        System.out.println("Remaining Prefix: " + prefix);
    }
}
